from auto import *
def union_hollow(n,label,c,roi,exclude=[],mins=3,shape='circle'):
 im=Image.open(f'images/fig_{n:03}.png');m=maskcolor(im,c);x0,y0,x1,y1=roi
 m[:y0]=False;m[y1:]=False;m[:,:x0]=False;m[:,x1:]=False
 for a,b,z,w in exclude:m[b:w,a:z]=False
 pts=[]
 for x,y,count,w,h in holes(m,mins):
  if w<2 or h<2 or w>10 or h>10:continue
  if shape=='triangle':y-=.7
  pts.append([x,y])
 for x,y,count,w,h in components(m,3):
  if 4<=w<=11 and 4<=h<=11 and all((x-p[0])**2+(y-p[1])**2>12 for p in pts):pts.append([x,y])
 pts.sort();return pts
if __name__=='__main__':
 for n,roi,exclude in [(91,(115,5,683,348),[(490,5,665,145)]),(5,(148,0,749,344),[(530,0,741,140)])]:
  D[f'fig_{n:03}.png']=[];out=[]
  for label,c,shape in [('x=0.00',(0,0,0),'circle'),('x=0.07',(255,0,255),'triangle'),('x=0.10',(0,255,255),'square'),('x=0.14',(0,255,0),'diamond')]:
   pts=union_hollow(n,label,c,roi,exclude,mins=4,shape=shape);add(n,label,pts,False);out.append((label,pts));print(n,label,len(pts))
  debug(n,out)
 save()
